    dx, dy = 0, 1
    for _ in range(K):
        if is_white(x, y):
            count += 1
        nx, ny = x + dx, y + dy
        if nx < 0 or nx >= R or ny < 0 or ny >= C:
            dx, dy = dy, -dx
            nx, ny = x + dx, y + dy
        x, y = nx, ny
    return count

