def count_grey_cells(R, C, K):
    def has_common_one_bit(x, y):
        return x & y != 0

    def count_greys_in_row(row):
        count = 0
        for col in range(C):
            if has_common_one_bit(row, col):
                count += 1
        return count

    def count_greys_in_column(col):
        count = 0
        for row in range(R):
            if has_common_one_bit(row, col):
                count += 1
        return count

    total_greys = 0
    for i in range(K):
        row = i // C
        col = i % C
        if (row + col) % 2 == 0:
            total_greys += count_greys_in_row(row)
        else:
            total_greys += count_greys_in_column(col)

    return total_greys

