def is_white(row, col):
    return any((row >> i) & 1 == (col >> i) & 1 for i in range(max(row.bit_length(), col.bit_length())))

@lru_cache(None)
def count_grey_cells(R, C, K):
    if K == 0:
        return 0
    if is_white(0, 0):
        return 1 + count_grey_cells(R, C, K - 1)
    else:
        return count_grey_cells(R, C, K - 1)

